changeSet.sql:
UPDATE roux_user u
   SET first_signed_in_at = (select min(s.signed_in_at) from who_session s where s.identity_id = u.id)
 WHERE first_signed_in_at IS NULL;

INSERT INTO who_role_permission (role_id, permission)
  SELECT r.id, 'users.owners' FROM who_role r WHERE r.name = 'OWNER'
  ON CONFLICT DO NOTHING;
